def solve(g, key):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    os_=objs(g)
    os_.sort(key=key, reverse=True)
    placed=set((r,c) for r in range(H) for c in range(W) if g[r][c])
    out=[[0]*W for _ in range(H)]
    for col,cells in os_:
        mr=max(r for r,c in cells); mc=max(c for r,c in cells)
        best=0
        for d in range(1, W-mc+1):
            if all((r,c+d) not in placed for r,c in cells): best=d
            else: break
        for r,c in cells:
            placed.discard((r,c)); placed.add((r,c+best))
            out[r][c+best]=col
    return out
